CREATE COLUMN TABLE "TEST_AP"."OVMC" ("AbsEntry" INTEGER CS_INT NOT NULL , "SYS_ID" INTEGER CS_INT, "ObjectId" INTEGER CS_INT, "Type" NVARCHAR(2) DEFAULT 'MD', "StartDate" LONGDATE CS_LONGDATE, "StartTime" INTEGER CS_INT, "EndDate" LONGDATE CS_LONGDATE, "EndTime" INTEGER CS_INT, "Message" NCLOB MEMORY THRESHOLD 1000, "Status" NVARCHAR(1) DEFAULT 'P', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 0  AUTO MERGE 